# CPU oracle is intentionally case-major and completed before creating the MJX rollout.
cq=np.empty((BATCH,STEPS,m.nq));cv=np.empty((BATCH,STEPS,m.nv));ca=np.empty((BATCH,STEPS),np.int32)
cg=np.zeros((BATCH,STEPS))
pq=np.empty((BATCH,STEPS,m.nq));pv=np.empty((BATCH,STEPS,m.nv));pw=np.empty((BATCH,STEPS,m.nv));pt=np.empty((BATCH,STEPS));cn=np.empty((BATCH,STEPS),np.int32)
for b in range(BATCH):
 d=mujoco.MjData(m);d.qpos[:]=Q[b];d.qvel[:]=V[b];d.ctrl[:]=C[b];mujoco.mj_forward(m,d)
 for t in range(STEPS):
  pq[b,t]=d.qpos;pv[b,t]=d.qvel;pw[b,t]=d.qacc_warmstart;pt[b,t]=d.time
  mujoco.mj_step(m,d);cq[b,t]=d.qpos;cv[b,t]=d.qvel;cn[b,t]=int(d.solver_niter[0]);cg[b,t]=float(d.solver.gradient[cn[b,t]-1]) if cn[b,t]>0 else 0.0
  ca[b,t]=int(np.count_nonzero(np.asarray(d.contact.dist[:d.ncon])<=0.0))
print('CPU_ORACLE_DONE',time.time(),flush=True)
mx=mjx.put_model(m,impl='jax');ds=[]
for b in range(BATCH):
 d=mujoco.MjData(m);d.qpos[:]=Q[b];d.qvel[:]=V[b];d.ctrl[:]=C[b];mujoco.mj_forward(m,d);ds.append(mjx.put_data(m,d,impl='jax'))
bd=jax.tree_util.tree_map(lambda *xs:jnp.stack(xs),*ds)
def trajectory(d):
 def one(x,_):
  y=mjx.step(mx,x)
  y=jax.tree_util.tree_map(lambda a,b:b.astype(a.dtype),x,y)  # x64: keep int32 contact indices stable in scan carry
  active=jnp.sum(y.contact.dist<=0.0)
  return y,(y.qpos,y.qvel,active)
 return lax.scan(one,d,None,length=STEPS)
# vmap over cases, one device-resident scan across every simulation step.
run=jax.jit(jax.vmap(trajectory))
t=time.perf_counter();_,out=run(bd);jax.block_until_ready(out);cold=time.perf_counter()-t
print('MJX_COLD_DONE',cold,flush=True)
t=time.perf_counter();_,out=run(bd);jax.block_until_ready(out);cached=time.perf_counter()-t
mq,mv,ma=map(np.asarray,out);ep=np.max(np.abs(cq-mq),2);ev=np.max(np.abs(cv-mv),2)
print('PRE_TF_PARITY',json.dumps({'max_qpos':float(ep.max()),'max_qvel':float(ev.max()),'oracle_max_grad':float(cg.max()),'cached_s':cached}),flush=True)
open('/kaggle/working/pre_tf_parity.json','w').write(json.dumps({'qpos_err':ep.tolist(),'qvel_err':ev.tolist(),'cpu_final_grad':cg.tolist(),'cold_s':cold,'cached_s':cached}))

# Teacher-forced one-step diagnostic: start MJX from the exact CPU pre-step state (incl. warmstart) at every step, vmapped over (case,step).
def one_from(d0,q,v,w,tm):
 x=d0.replace(qpos=q,qvel=v,qacc_warmstart=w,time=tm)
 y=mjx.step(mx,x)
 return y.qpos,y.qvel,jnp.asarray(getattr(y,'solver_niter',jnp.zeros(1))).reshape(-1)[0],jnp.sum(y.contact.dist<=0.0)
# Memory-bounded: lax.map over flattened (case,step) with small device batches instead of a full nested vmap (v11 OOM at 16.7 GB).
def one_flat(args):
 c,q,v,w,tm=args
 d0=jax.tree_util.tree_map(lambda a:a[c],bd)
 return one_from(d0,q,v,w,tm)
cidx=jnp.repeat(jnp.arange(BATCH),STEPS)
flat=(cidx,jnp.asarray(pq).reshape(BATCH*STEPS,-1),jnp.asarray(pv).reshape(BATCH*STEPS,-1),jnp.asarray(pw).reshape(BATCH*STEPS,-1),jnp.asarray(pt).reshape(-1))
tf=jax.jit(lambda xs:lax.map(one_flat,xs,batch_size=8))
print('TF_START',time.time(),flush=True)
tq,tv,tn,ta=[np.asarray(a).reshape((BATCH,STEPS)+np.asarray(a).shape[1:]) for a in tf(flat)]
oq=np.max(np.abs(cq-tq),2);ov=np.max(np.abs(cv-tv),2)
onestep={'qpos_err':oq.tolist(),'qvel_err':ov.tolist(),'cpu_solver_niter':cn.tolist(),'mjx_solver_niter':tn.astype(int).tolist(),'mjx_active':ta.astype(int).tolist(),'max_qpos':float(oq.max()),'max_qvel':float(ov.max()),'worst_step_qvel':[int(np.argmax(r)) for r in ov]}
print('ONESTEP',json.dumps({k:onestep[k] for k in ['max_qpos','max_qvel','worst_step_qvel']}),flush=True)
def cross(x,th):return [None if not np.any(a>th) else int(np.argmax(a>th)) for a in x]
oracle_converged=bool(cg.max()<=1e-6)
passed=bool(ep.max()<=QP_TOL and ev.max()<=QV_TOL and oracle_converged)
report={'fixture':'h2_parity_v14_official_limits_armature_float64_b4s50_tfmap','steps':STEPS,'batch':BATCH,'duration_s':STEPS*float(m.opt.timestep),'versions':{'mujoco':mujoco.__version__,'jax':jax.__version__},'devices':[str(x) for x in jax.devices()],'model':{'nq':m.nq,'nv':m.nv,'nu':m.nu,'ngeom':m.ngeom,'xml_sha256':hashlib.sha256(open(XML,'rb').read()).hexdigest(),'isolation_change':'v14: official H2 effort limits + joint ranges (unitree_ros H2_loop.xml/H2.urdf), armature 0.01 damping 0.05 frictionloss 0.2; original physics (condim 6, elliptic, all collisions) with solver budget iterations 8->100, ls_iterations 8->50 on both backends; MJX float64; CPU oracle convergence gated','x64':bool(jax.config.jax_enable_x64)},'solver':{'integrator':int(m.opt.integrator),'solver':int(m.opt.solver),'iterations':int(m.opt.iterations),'ls_iterations':int(m.opt.ls_iterations),'tolerance':float(m.opt.tolerance),'ls_tolerance':float(m.opt.ls_tolerance),'cone':int(m.opt.cone),'impratio':float(m.opt.impratio),'noslip_iterations':int(m.opt.noslip_iterations),'timestep':float(m.opt.timestep)},'vectorization':{'time':'jax.lax.scan','environments':'jax.vmap','host_step_loop':False},'timing':{'cold_compile_and_rollout_s':cold,'cached_rollout_s':cached,'env_steps_per_s':BATCH*STEPS/cached},'thresholds':{'max_qpos':QP_TOL,'max_qvel':QV_TOL},'qpos_error':{'max':float(ep.max()),'per_case_max':ep.max(1).tolist(),'first_cross_1e-4':cross(ep,QP_TOL)},'qvel_error':{'max':float(ev.max()),'per_case_max':ev.max(1).tolist(),'first_cross_1e-3':cross(ev,QV_TOL)},'per_step':{'qpos_max_across_cases':ep.max(0).tolist(),'qvel_max_across_cases':ev.max(0).tolist()},'contact':{'cpu_active_dist_le_0':ca.tolist(),'mjx_active_dist_le_0':ma.tolist(),'counts_equal_all_steps':bool(np.array_equal(ca,ma)),'gated':False,'note':'Active contacts use dist<=0 on both backends; counts are diagnostic and do not gate parity.'},'oracle':{'converged':oracle_converged,'max_final_gradient':float(cg.max()),'max_niter':int(cn.max())},'pass':passed,'teacher_forced_one_step':onestep}
open('/kaggle/working/h2_parity_report.json','w').write(json.dumps(report,indent=2));print('PARITY_SUMMARY',json.dumps({'oracle':{'converged':oracle_converged,'max_final_gradient':float(cg.max()),'max_niter':int(cn.max())},'pass':passed,'max_qpos':float(ep.max()),'max_qvel':float(ev.max()),'contacts_equal':bool(np.array_equal(ca,ma)),'timing':report['timing']}),flush=True)

# Stage-1 standing/balance smoke is forbidden until its independent parity gate passes.
training={'started':False,'reason':'precision-isolation diagnostic only; training intentionally disabled','environment':'minimal H2: floor, gravity, rigid contacts, actuators; no tennis apparatus'}
if False and passed:
 TRAIN_ENVS=8; HORIZON=8; UPDATES=3; LR=2e-3
 q0=jnp.asarray(base.qpos);ctrl0=jnp.asarray(base.ctrl);lo=jnp.asarray(m.actuator_ctrlrange[:,0]);hi=jnp.asarray(m.actuator_ctrlrange[:,1])
 obs_dim=m.nq+m.nv;key=jax.random.PRNGKey(19)
 params={'w':jnp.zeros((m.nu,obs_dim),jnp.float32),'b':ctrl0.astype(jnp.float32)}
 opt=optax.adam(LR);opt_state=opt.init(params)
 def reset_one(k):
  d=mjx.make_data(mx);k1,k2=jax.random.split(k);q=q0.at[0:2].add(jax.random.uniform(k1,(2,),minval=-.02,maxval=.02));v=jax.random.normal(k2,(m.nv,))*0.01
  return d.replace(qpos=q,qvel=v,ctrl=ctrl0)
 def loss_fn(p,keys):
  states=jax.vmap(reset_one)(keys)
  def one_step(ds,_):
   obs=jnp.concatenate([ds.qpos,ds.qvel],axis=-1);a=jnp.clip(obs@p['w'].T+p['b'],lo,hi);ds=ds.replace(ctrl=a);nxt=jax.vmap(lambda x:mjx.step(mx,x))(ds)
   quat=nxt.qpos[:,3:7];upright=1.0-2.0*(quat[:,1]**2+quat[:,2]**2);height=nxt.qpos[:,2]
   r=2.0*upright+jnp.exp(-20.0*(height-q0[2])**2)-1e-4*jnp.sum(a*a,axis=-1)-2.0*jnp.square(nxt.qvel[:,2])
   return nxt,r
  _,rs=lax.scan(one_step,states,None,length=HORIZON);return -jnp.mean(rs),{'reward':jnp.mean(rs),'final_reward':jnp.mean(rs[-1])}
 value_grad=jax.jit(jax.value_and_grad(loss_fn,has_aux=True));history=[];t0=time.perf_counter()
 for u in range(UPDATES):
  key,sk=jax.random.split(key);keys=jax.random.split(sk,TRAIN_ENVS);(loss,metrics),grads=value_grad(params,keys);updates,opt_state=opt.update(grads,opt_state,params);params=optax.apply_updates(params,updates);jax.block_until_ready(loss)
  history.append({'update':u+1,'loss':float(loss),'mean_reward':float(metrics['reward']),'final_reward':float(metrics['final_reward'])})
 ckpt='/kaggle/working/h2_stage1_smoke_checkpoint.pkl'
 with open(ckpt,'wb') as f:pickle.dump({'params':jax.device_get(params),'opt_state':jax.device_get(opt_state),'update':UPDATES,'history':history},f)
 # Prove that a fresh in-run load resumes and executes another optimizer update.
 with open(ckpt,'rb') as f:loaded=pickle.load(f)
 resumed_params=jax.tree_util.tree_map(jnp.asarray,loaded['params']);resumed_opt=jax.tree_util.tree_map(jnp.asarray,loaded['opt_state']);key,sk=jax.random.split(key);keys=jax.random.split(sk,TRAIN_ENVS)
 (loss,metrics),grads=value_grad(resumed_params,keys);updates,resumed_opt=opt.update(grads,resumed_opt,resumed_params);resumed_params=optax.apply_updates(resumed_params,updates);jax.block_until_ready(loss)
 resume_ckpt='/kaggle/working/h2_stage1_smoke_resumed.pkl'
 with open(resume_ckpt,'wb') as f:pickle.dump({'params':jax.device_get(resumed_params),'opt_state':jax.device_get(resumed_opt),'update':UPDATES+1},f)
 training={'started':True,'algorithm':'differentiable MJX policy-gradient smoke (PPO is the later full run)','environment':'minimal H2: floor, gravity, rigid contacts, actuators; no tennis apparatus','vectorization':{'time':'jax.lax.scan','environments':'jax.vmap','host_step_loop':False},'envs':TRAIN_ENVS,'horizon':HORIZON,'updates':UPDATES,'elapsed_s':time.perf_counter()-t0,'initial_reward':history[0]['mean_reward'],'final_reward':history[-1]['mean_reward'],'checkpoint':ckpt,'resume_checkpoint':resume_ckpt,'resume_verified_update':UPDATES+1,'history':history}
open('/kaggle/working/h2_stage1_smoke_report.json','w').write(json.dumps(training,indent=2));print('TRAINING_SUMMARY',json.dumps({k:training[k] for k in training if k!='history'}),flush=True)
